select * from (values
  ($q$BLIND BOX 26 · THE ROYAL OUD DROP IS LIVE NOW$q$, $q${"type":"collection","value":"royal"}$q$::jsonb, false, 0),
  ($q$FREE 5 ML SAMPLES WITH EVERY 50 ML OF PERFUME$q$, null::jsonb, false, 1),
  ($q$FREE INSURED DELIVERY ACROSS INDIA ON ORDERS OVER RS. 4,999$q$, $q${"type":"page","value":"shipping-policy"}$q$::jsonb, false, 2)
) v(text, link, is_active, position)
where not exists (select 1 from public.announcements);

