  ($q$Taif Rose Alchemy$q$, $q$Picked at Dawn in the Mountains of Saudi Arabia$q$, $q$BOTANICAL$q$, $q$/images/saudagar_imperial_ruby.png$q$, null, 5000, (select id from public.products where slug = $q$saudagar-oud-roses$q$), true, 1),
  ($q$001 Deep Canopy$q$, $q$Volcanic Flint & Crushed Cypress Needles$q$, $q$SIGNATURE$q$, $q$/images/saudagar_noir_matte.png$q$, null, 5000, (select id from public.products where slug = $q$saudagar-deep-canopy$q$), true, 2),
  ($q$The Atelier Flacon$q$, $q$Heavy Crystal Hand-Cut in Val-de-Sambre$q$, $q$CRAFTSMANSHIP$q$, $q$/images/saudagar_crystal_diamond.png$q$, null, 5000, (select id from public.products where slug = $q$saudagar-masterpiece-coffret$q$), true, 3),
  ($q$Sapphire Sol Marine$q$, $q$Crisp Sea Salt & Sun-Drenched Bergamot$q$, $q$AQUATIC$q$, $q$/images/saudagar_royal_sapphire.png$q$, null, 5000, (select id from public.products where slug = $q$saudagar-pacific-chill$q$), true, 4)
