-- testimonials
insert into public.testimonials (quote, name, location, rating, product_id, is_active, position)
select * from (values
  ($q$Replace this with a real customer quote about the fragrance and the experience.$q$, $q$Customer Name$q$, $q$City$q$, 5, null::uuid, false, 0),
  ($q$Replace this with a second real customer quote, ideally mentioning a specific note or moment.$q$, $q$Customer Name$q$, $q$City$q$, 5, null::uuid, false, 1),
  ($q$Replace this with a third real customer quote about packaging, delivery or longevity.$q$, $q$Customer Name$q$, $q$City$q$, 5, null::uuid, false, 2)
) v(quote, name, location, rating, product_id, is_active, position)
where not exists (select 1 from public.testimonials);

