-- reels and the products tagged in them
do $reels$
declare
  r record;
  new_id uuid;
begin
  if exists (select 1 from public.reels) then
    return;
  end if;
  for r in
    select * from jsonb_to_recordset($q$[{"title":"The Unboxing Ritual: Thunderstruck Oud Extrait","caption":"Original Sound · Saudagar Private Salon","video_url":null,"thumbnail_url":"/images/saudagar_amber_gold.png","external_url":null,"product_slugs":["saudagar-thunderstruck-oud"],"is_active":true,"position":0},{"title":"Harvesting Rare Taif Roses at Dawn in Saudi Arabia","caption":"Acoustic Oud & Ambient Sillage","video_url":null,"thumbnail_url":"/images/saudagar_imperial_ruby.png","external_url":null,"product_slugs":["saudagar-oud-roses"],"is_active":true,"position":1},{"title":"18-Year Aged Cambodi Oud Oil Distillation in Assam","caption":"Atelier Artisan Notes · Sacred Copper","video_url":null,"thumbnail_url":"/images/saudagar_noir_matte.png","external_url":null,"product_slugs":["saudagar-deep-canopy"],"is_active":true,"position":2},{"title":"The 6-Flacon Discovery Coffret: Six Iconic Extraits","caption":"Saudagar Masterwork Discovery","video_url":null,"thumbnail_url":"/images/saudagar_crystal_diamond.png","external_url":null,"product_slugs":["saudagar-masterpiece-coffret"],"is_active":true,"position":3},{"title":"Sapphire Sol Marine: Coastal Salt & Radiant Citrus","caption":"Riviera Morning Sea Breeze","video_url":null,"thumbnail_url":"/images/saudagar_royal_sapphire.png","external_url":null,"product_slugs":["saudagar-pacific-chill"],"is_active":true,"position":4},{"title":"Obsidian Root: Smoked Birch & Dark Frankincense","caption":"Smoked Wood Alchemy","video_url":null,"thumbnail_url":"/images/crystal_square_flacon.png","external_url":null,"product_slugs":["saudagar-obsidian-root"],"is_active":true,"position":5}]$q$::jsonb)
      as t(title text, caption text, video_url text, thumbnail_url text, external_url text, product_slugs text[], is_active boolean, position int)
  loop
    insert into public.reels (title, caption, video_url, thumbnail_url, external_url, is_active, position)
    values (r.title, r.caption, r.video_url, r.thumbnail_url, r.external_url, coalesce(r.is_active, true), r.position)
    returning id into new_id;
    insert into public.reel_products (reel_id, product_id, position)
    select new_id, p.id, s.ord - 1
    from unnest(coalesce(r.product_slugs, '{}')) with ordinality as s(slug, ord)
    join public.products p on p.slug = s.slug;
  end loop;
end
$reels$;
